#include <bits/stdc++.h>
using namespace std;
int n, basep; vector<array<int,2>> opt; vector<vector<int>> perms,parts;
int gcdx(int a,int b){return std::gcd(abs(a),abs(b));}
void genparts(vector<int>& p,int mx){int j=p.size(); if(j==n){if(mx>=1 && mx+1<n)parts.push_back(p); return;}for(int c=0;c<=mx+1;c++){p.push_back(c);genparts(p,max(mx,c));p.pop_back();}}
void gen(int N){n=N;opt.clear();for(int a=0;a<n;a++)for(int b=a;b<n;b++)opt.push_back({a,b});basep=opt.size();parts.clear();vector<int> p={0};genparts(p,0);perms.clear();vector<int> perm(n);iota(perm.begin(),perm.end(),0);do{perms.push_back(perm);}while(next_permutation(perm.begin(),perm.end()));}
void decode(uint64_t code,vector<array<int,2>>& a){a.resize(n);for(int i=0;i<n;i++){a[i]=opt[code%basep];code/=basep;}}
int indexpair(int a,int b){if(a>b)swap(a,b);return a*n-a*(a-1)/2+(b-a);}
uint64_t encode(const vector<array<int,2>>& a){uint64_t v=0,rad=1;for(int i=0;i<n;i++){v+=rad*indexpair(a[i][0],a[i][1]);rad*=basep;}return v;}
uint64_t transform(const vector<array<int,2>>& a,const vector<int>& p){uint64_t r=0,rad=1;int pos[8]={};for(int u=0;u<n;u++)pos[p[u]]=indexpair(p[a[u][0]],p[a[u][1]]);for(int i=0;i<n;i++){r+=rad*pos[i];rad*=basep;}return r;}
bool canonical(const vector<array<int,2>>& a,uint64_t orig){for(const auto& p:perms){if(transform(a,p)<orig)return false;}return true;}
int orbit_size(const vector<array<int,2>>& a,uint64_t orig){int auto_count=0;for(const auto& p:perms)if(transform(a,p)==orig)auto_count++;return perms.size()/auto_count;}
bool primitive(const vector<array<int,2>>& a){int d[8];fill(d,d+n,-1);d[0]=0;queue<int>q;q.push(0);while(!q.empty()){int u=q.front();q.pop();for(int v:a[u])if(d[v]<0){d[v]=d[u]+1;q.push(v);}}for(int i=0;i<n;i++)if(d[i]<0)return false;int rev[8]={};rev[0]=1;q.push(0);while(!q.empty()){int v=q.front();q.pop();for(int u=0;u<n;u++)for(int w:a[u])if(w==v&&!rev[u]){rev[u]=1;q.push(u);}}for(int i=0;i<n;i++)if(!rev[i])return false;int g=0;for(int u=0;u<n;u++)for(int v:a[u])g=gcdx(g,d[u]+1-d[v]);return g==1;}
bool lumpable(const vector<array<int,2>>& a,const vector<int>& p){int counts[8][8]={};for(int u=0;u<n;u++)for(int v:a[u])counts[u][p[v]]++;for(int u=0;u<n;u++)for(int v=0;v<u;v++)if(p[u]==p[v])for(int c=0;c<n;c++)if(counts[u][c]!=counts[v][c])return false;return true;}
long long det(vector<vector<long long>> a){int m=a.size();long long denom=1,sign=1;for(int k=0;k<m-1;k++){if(a[k][k]==0){int sw=k+1;while(sw<m&&a[sw][k]==0)sw++;if(sw==m)return 0;swap(a[k],a[sw]);sign=-sign;}long long pivot=a[k][k];for(int i=k+1;i<m;i++)for(int j=k+1;j<m;j++) {long long num=a[i][j]*pivot-a[i][k]*a[k][j];if(num%denom){cerr<<"bad det";exit(2);}a[i][j]=num/denom;}for(int i=k+1;i<m;i++)a[i][k]=0;denom=pivot;}return sign*a[m-1][m-1];}
vector<long long> pf(const vector<array<int,2>>& a){vector<vector<long long>> L(n,vector<long long>(n));for(int i=0;i<n;i++)L[i][i]=2;for(int u=0;u<n;u++)for(int v:a[u])L[v][u]--;vector<long long> v(n);long long g=0;for(int k=0;k<n;k++){vector<vector<long long>> sub;for(int i=0;i<n;i++)if(i!=k){vector<long long>row;for(int j=0;j<n;j++)if(j!=k)row.push_back(L[i][j]);sub.push_back(row);}v[k]=det(sub);g=gcdx(g,v[k]);}for(auto&x:v)x/=g;return v;}
bool sync(const vector<array<int,2>>& a,int bits){int T[2][8];for(int i=0;i<n;i++){T[(bits>>i)&1][i]=a[i][0];T[1-((bits>>i)&1)][i]=a[i][1];} bool vis[1<<8]={};queue<int>q;int start=(1<<n)-1;vis[start]=1;q.push(start);while(!q.empty()){int mask=q.front();q.pop();if((mask&(mask-1))==0)return true;for(int l=0;l<2;l++){int dest=0;for(int u=0;u<n;u++)if(mask>>u&1)dest|=1<<T[l][u];if(!vis[dest]){vis[dest]=1;q.push(dest);}}}return false;}
int main(int argc,char**argv){n=(argc>1)?atoi(argv[1]):5;gen(n);uint64_t total=1;for(int i=0;i<n;i++)total*=basep;long long cp=0,ct=0,cs=0,cns=0,cf=0;map<int,array<long long,4>> hist;map<tuple<int,int,int>,int> joint;long long label_prim=0,label_total=0,label_simple=0,label_both=0;int first_simple_not_total=0;string example;cout<<"# n="<<n<<" total="<<total<<" partitions="<<parts.size()<<"\n";for(uint64_t code=0;code<total;code++){vector<array<int,2>> a;decode(code,a);if(!primitive(a))continue;if(!canonical(a,code))continue;cp++;int orbit=orbit_size(a,code);label_prim+=orbit;bool l=false;for(auto&p:parts)if(lumpable(a,p)){l=true;break;}int sy=0;for(int color=0;color<(1<<n);color++)sy+=sync(a,color);bool totally=sy==(1<<n);bool simple=!l;vector<long long>v=pf(a);int equip=0;for(auto&p:parts){long long sums[8]={};int mx=*max_element(p.begin(),p.end());for(int i=0;i<n;i++)sums[p[i]]+=v[i];bool eq=true;for(int i=1;i<=mx;i++)if(sums[i]!=sums[0])eq=false;if(eq)equip++;}if(totally)ct++;if(simple)cs++;if(simple&&!totally){cns++;if(!first_simple_not_total){example=to_string(code);first_simple_not_total=1;}}if(totally&&simple)cf++;int cat=(totally?1:0)+(simple?2:0);hist[sy][cat]++;joint[{cat,equip,sy}]++;if(totally)label_total+=orbit;if(simple)label_simple+=orbit;if(totally&&simple)label_both+=orbit;cout<<"R,"<<code<<","<<orbit<<","<<sy<<","<<simple<<","<<equip<<",";for(int i=0;i<n;i++){if(i)cout<<";";cout<<a[i][0]<<":"<<a[i][1];}cout<<",";for(int i=0;i<n;i++){if(i)cout<<":";cout<<v[i];}cout<<"\n";}
cerr<<"n "<<n<<" primitive_classes="<<cp<<" total_classes="<<ct<<" simple_classes="<<cs<<" simple_non_total="<<cns<<" simple_and_total="<<cf<<" orbit_primitive="<<label_prim<<" orbit_total="<<label_total<<" orbit_simple="<<label_simple<<" orbit_both="<<label_both<<"\n";
for(auto [s,x]:hist){cerr<<"hist "<<s<<" nonSimpleNonTotal="<<x[0]<<" nonSimpleTotal="<<x[1]<<" simpleNonTotal="<<x[2]<<" simpleTotal="<<x[3]<<"\n";}return 0;}
